// components/public/storefront-trust-bar.tsx — Minimalist Full-Screen Buyer Protection Section
// Palette: Obsidian Velvet & Soft Alabaster (Linear/Raycast Style)
// 1. Soft Alabaster (#F8F9FA) in Light Mode — zero eye glare, not blinding pure white
// 2. Obsidian Charcoal (#0D0E12) in Dark Mode — zero OLED halation, not harsh pure black
// 3. Crisp bone white / charcoal text hierarchy with calibrated contrast (4.5:1+)
// 4. Pure Monochromatic — zero color distractions, zero gradients
// 5. Full-screen height (min-h-[100dvh] flex flex-col justify-center)

"use client";

import React from "react";
import { motion, useReducedMotion } from "framer-motion";
import { ArrowDown } from "lucide-react";
import { sfx } from "@/src/lib/sound-effects";

export interface TrustGuarantee {
  step: string;
  label: string;
  title: string;
  assurance: string;
}

export const GUARANTEES: TrustGuarantee[] = [
  {
    step: "01",
    label: "AUTOMATED FULFILLMENT",
    title: "Immediate Delivery",
    assurance:
      "Your credentials unlock directly on screen and in Telegram the instant payment is confirmed.",
  },
  {
    step: "02",
    label: "VERIFIED CREDENTIALS",
    title: "Private Solo Access",
    assurance:
      "100% verified, private accounts with zero shared access, screen collisions, or interruptions.",
  },
  {
    step: "03",
    label: "COMPLETE PROTECTION",
    title: "24-Hour Guarantee",
    assurance:
      "Instant automated replacement if any issue arises. You are completely protected from risk.",
  },
];

export function StorefrontTrustBar() {
  const shouldReduceMotion = useReducedMotion();

  const handleScrollToFloor = (e: React.MouseEvent) => {
    e.preventDefault();
    sfx.playKeypadClick();
    const el = document.getElementById("floor");
    if (typeof window !== "undefined" && (window as any).__lenis && el) {
      (window as any).__lenis.scrollTo(el, { offset: -20, duration: 1.0 });
    } else if (el) {
      el.scrollIntoView({ behavior: "smooth", block: "start" });
    }
  };

  return (
    <section
      id="guarantees"
      aria-label="Buyer protection and guarantee pillars"
      className="w-full min-h-[100dvh] flex flex-col justify-center relative z-20 py-16 sm:py-24 border-y border-neutral-200/80 dark:border-white/10 bg-transparent transition-colors"
    >
      <div className="max-w-7xl mx-auto px-6 sm:px-10 lg:px-14 w-full">
        {/* ── SECTION HEADER: Calm & Direct ── */}
        <div className="flex flex-col md:flex-row md:items-end justify-between gap-6 mb-16 sm:mb-20 pb-8 border-b border-neutral-200 dark:border-white/10">
          <div className="text-left max-w-2xl">
            <span className="text-[11px] font-mono tracking-[0.25em] text-neutral-600 dark:text-[#8F96A3] uppercase select-none block mb-3 font-medium">
              BUYER PROTECTION SYSTEM
            </span>
            <h2 className="text-3xl sm:text-4xl lg:text-5xl font-bold tracking-tight text-[#121316] dark:text-[#EDEDF0] font-sans">
              Built on verified guarantees.
            </h2>
            <p className="text-sm sm:text-base text-neutral-600 dark:text-[#8F96A3] mt-3 font-sans leading-relaxed">
              Every allocation is protected by automated verification and dedicated replacement protocols.
            </p>
          </div>

          <a
            href="#floor"
            onClick={handleScrollToFloor}
            className="inline-flex items-center gap-2 text-xs font-mono tracking-wider text-neutral-600 dark:text-[#8F96A3] hover:text-[#121316] dark:hover:text-[#EDEDF0] transition-colors cursor-pointer group uppercase self-start md:self-end focus-visible:ring-2 focus-visible:ring-neutral-400 dark:focus-visible:ring-white/40 focus-visible:outline-none rounded-md px-2 py-1"
          >
            <span>Proceed to catalog floor</span>
            <ArrowDown className="w-3.5 h-3.5 transition-transform group-hover:translate-y-0.5" />
          </a>
        </div>

        {/* ── 3 MINIMALIST TYPOGRAPHIC COLUMNS (NO BOXES, NO PILLS, SUBTLE HAIRLINES) ── */}
        <div className="grid grid-cols-1 md:grid-cols-3 gap-12 sm:gap-14 lg:gap-16">
          {GUARANTEES.map((item, idx) => (
            <motion.div
              key={item.step}
              initial={shouldReduceMotion ? false : { opacity: 0, y: 16 }}
              whileInView={{ opacity: 1, y: 0 }}
              viewport={{ once: true, margin: "-50px" }}
              transition={{ duration: 0.45, delay: idx * 0.12, ease: [0.23, 1, 0.32, 1] }}
              className="flex flex-col text-left md:pr-10 last:pr-0 border-b md:border-b-0 md:border-r border-neutral-200 dark:border-white/10 last:border-r-0 pb-10 md:pb-0"
            >
              {/* Step Number in Soft Zinc Monospace (WCAG AA Compliant) */}
              <div className="font-mono text-3xl sm:text-4xl font-extralight text-[#5A606E] dark:text-[#7A8290] tracking-tight mb-4 select-none">
                {item.step}
              </div>

              {/* Sub-label */}
              <div className="text-[10px] font-mono tracking-[0.2em] text-neutral-600 dark:text-[#8F96A3] uppercase mb-2 select-none font-medium">
                {item.label}
              </div>

              {/* Clean Title */}
              <h3 className="text-xl sm:text-2xl font-bold tracking-tight text-[#121316] dark:text-[#EDEDF0] font-sans mb-3">
                {item.title}
              </h3>

              {/* Calming Single-Sentence Assurance */}
              <p className="text-sm sm:text-base text-neutral-800 dark:text-neutral-300 leading-relaxed font-sans">
                {item.assurance}
              </p>
            </motion.div>
          ))}
        </div>
      </div>
    </section>
  );
}

export default StorefrontTrustBar;
